{
  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    retained = set(node_map.keys())
    removal_order = []
    candidate_ids = sorted(node_map.keys(), key=lambda x: (-node_map[x]['depth'], x))
    changed = True
    while changed:
        changed = False
        for nid in candidate_ids:
            if nid not in retained:
                continue
            node = node_map[nid]
            if node['parent'] is None:
                continue
            if not node['removable']:
                continue
            if node['symbol'] in required_symbols:
                continue
            if any(c in retained for c in children[nid]):
                continue
            retained.remove(nid)
            removal_order.append(nid)
            changed = True
    sorted_retained = sorted(retained)
    return {'retained': sorted_retained, 'removal_order': removal_order}"
}
